            : `<div class="sp-instructor-avatar-placeholder">${initials}</div>`
        }
        <div class="sp-instructor-info">
          <div class="sp-instructor-name">${escapeHtml(instructor.name)}</div>
          ${instructor.bio ? `<div class="sp-instructor-bio">${escapeHtml(instructor.bio)}</div>` : ""}
        </div>
