  if (blueprint?.muscleAreas?.length) {
    const mount = document.getElementById("muscleAnatomyMount");
    if (mount) renderMuscleMap(blueprint.muscleAreas, mount);
  }

  // ── Update sticky footer meta row ──
  const footerMeta = document.getElementById("oc-footer-meta");
  if (footerMeta) {
    footerMeta.innerHTML = `
      <span class="oc-footer-meta-item">${calSvg}<span>${dateLabel}</span></span>
      <span class="oc-footer-meta-item">${clockSvg}<span>${time} (${duration} min)</span></span>`;
  }

  // ── SPM-98 — "Make it a Duo Class" opt-in (PRIVATE only) ──
  // Books the SAME session for 2 seats; the single booker covers both.
  // Hidden for GROUP (the checkout quantity stepper handles those) and when
  // the session can't seat a second person (e.g. someone else already booked).
  const duoToggle = document.getElementById("duoToggle");
  const duoCheckbox = document.getElementById("duoCheckbox");
  if (duoToggle && duoCheckbox) {
    const isPrivate = session.format === "PRIVATE";
    // A PRIVATE session is 1-on-1 (capacity 1, no current bookings). The duo
    // upgrades it to 2 seats, so only offer it while the slot is still empty.
    const canDuo = isPrivate && !isFull && spotsLeft >= 1;
    duoCheckbox.checked = false; // reset each time the panel opens
    duoToggle.style.display = canDuo ? "flex" : "none";
  }

  // ── Cancel policy note (hours from live API) ──
  const cancelNote = document.getElementById("oc-cancel-note");
  const cancelRows = document.getElementById("oc-cancel-rows");
  if (cancelNote && cancelRows) {
    const p = cancelPolicy;
    const checkSvgSm = `<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5" style="width:12px;height:12px;flex-shrink:0;"><polyline points="20 6 9 17 4 12"/></svg>`;
    const rows = [
      { hours: p.cancelWindowHoursCreditGroup,  label: "Credit" },
      { hours: p.cancelWindowHoursOnlineGroup,  label: "Online" },
      { hours: p.cancelWindowHoursStudioGroup,  label: "At studio" },
    ].filter((r) => r.hours != null && r.hours > 0);

    if (rows.length === 0 || isFull) {
      cancelNote.style.display = "none";
    } else {
      cancelRows.innerHTML = rows
        .map((r) => `<span class="oc-cancel-row">${checkSvgSm}<span>${r.hours}h &mdash; ${r.label}</span></span>`)
        .join("");
      cancelNote.style.display = "flex";
    }
  }
}

