  biceps: "#F4511E",
  triceps: "#FF8A65",
  forearm: "#FFAB91",
  trapezius: "#C0392B",
  "upper-trapezius": "#E74C3C",
  "lower-trapezius": "#A93226",
  "upper-back": "#D84315",
  "lower-back": "#BF360C",
