  "hip-flexors": "#F57C00",
  adductors: "#FB8C00",
  neck: "#E65100",
  knees: "#FF8F00",
  feet: "#FFAB40",
  ankles: "#FFD740",
  hands: "#FFC107",
  head: "#D84315",
};

let _viewerFront = null;
let _viewerBack = null;
let _viewerMountEl = null;

function renderMuscleMap(areas, mountEl) {
  if (_viewerMountEl !== mountEl) {
    _viewerFront?.destroy();
    _viewerBack?.destroy();
    _viewerFront = null;
    _viewerBack = null;
    _viewerMountEl = mountEl;
  }
  mountEl.innerHTML =
    '<div class="sp-muscle-map-wrap">' +
    '<div class="sp-muscle-map-col"><span class="sp-muscle-map-label">Front</span><div id="mmViewFront" style="width:100px;height:218px;"></div></div>' +
    '<div class="sp-muscle-map-col"><span class="sp-muscle-map-label">Back</span><div id="mmViewBack"  style="width:100px;height:218px;"></div></div>' +
    "</div>";

  const frontEl = document.getElementById("mmViewFront");
  const backEl = document.getElementById("mmViewBack");
  const opts = {
    gender: "female",
    interactive: false,
    style: "minimal",
    showSubGroups: false,
  };
  _viewerFront = new MuscleMapWidget(frontEl, { ...opts, side: "front" });
  _viewerBack = new MuscleMapWidget(backEl, { ...opts, side: "back" });
  _viewerFront.enableTooltip((m) => getMuscleName(m));
  _viewerBack.enableTooltip((m) => getMuscleName(m));
  areas.forEach((muscle) => {
    const color = MUSCLE_COLORS[muscle] ?? "#FF6B35";
    _viewerFront.highlight(muscle, color, 0.85);
    _viewerBack.highlight(muscle, color, 0.85);
  });
}

// ── Global handlers ──
window.closeDetails = function () {
  document.getElementById("detailsOverlay").classList.remove("open");
  document.body.style.overflow = "";
  currentSessionId = null;
};

window.bookClass = function () {
  if (!currentSessionId) return;

  // ── Guest-checkout gate ──
  // If the admin has disabled guest booking, intercept unauthenticated users
  // HERE, before navigating to checkout, with a friendly in-offcanvas prompt.
  const token = localStorage.getItem("customer_token");
  if (!token && cancelPolicy.allowGuestCheckout === false) {
    showBookingLoginPrompt(currentSessionId);
    return;
  }

  // SPM-98 — carry the "Make it a Duo Class" opt-in (PRIVATE only) through to
