/// <summary>
/// Reserve a spot — creates RESERVED attendance without deducting credits.
/// Credit deduction only happens on admin check-in.
/// </summary>
[AllowAnonymous]
[HttpPost("reserve")]
public async Task<IActionResult> ReserveSpot([FromBody] ReserveRequest request)
{
    if (string.IsNullOrWhiteSpace(request.SessionId))
        return BadRequest(new { message = "SessionId is required." });
    if (string.IsNullOrWhiteSpace(request.Name))
        return BadRequest(new { message = "Name is required." });
    if (string.IsNullOrWhiteSpace(request.Phone))
        return BadRequest(new { message = "Phone number is required." });

    // Guest guard: if this email/phone already belongs to a registered account,
    // steer the guest to log in instead of booking anonymously (prevents a
    // duplicate account and keeps the booking on the right profile). Skipped for
    // authenticated requests — a logged-in customer legitimately books with their
    // own contact details (which would otherwise match their own account).
    if (User?.Identity?.IsAuthenticated != true)
    {
        var match = await _customerAuth.MatchExistingAccountAsync(request.Email, request.Phone);
        if (match != null)
        {
            return Conflict(new
            {
                requiresLogin = true,
                matchedBy = match,
                message = match == "email"
                    ? "You already have an account with this email. Please log in to book."
                    : "You already have an account with this phone number. Please log in to book."
            });
        }
    }

    // Find or create client
    var client = await _clientService.FindByPhoneOrEmailAsync(request.Phone, request.Email);
    string clientId;

    if (client != null)
    {
        clientId = client.Id!;
    }
    else
    {
        // Auto-create client record for new visitors
        var newClient = new Client
        {
            FullName = request.Name,
            PhoneNumber = request.Phone,
            Email = request.Email,
            ContactPlatform = "NONE",
            CountryOfOrigin = "Vietnam"
        };
        var created = await _clientService.CreateClientAsync(newClient);
        clientId = created.Id!;
    }

    // Find matching active package for the session format
    var session = await _schedulingService.GetSessionByIdAsync(request.SessionId);
    if (session == null) return NotFound(new { message = "Session not found." });

    string? packageId = null;
    if (!string.IsNullOrWhiteSpace(request.PackageId))
    {
        packageId = request.PackageId;
    }
    else
    {
        // Auto-match: find an active package matching the session format
        var packages = await _walletService.GetActivePackagesForClientAsync(clientId, session.Format);
        packageId = packages.FirstOrDefault()?.Id;
    }

    try
    {
        var attendance = await _schedulingService.ReserveSpotAsync(
            request.SessionId, clientId, request.Name, request.Phone, request.Email, packageId,
            request.Goals, request.EquipmentType,
            quantity: request.Quantity,
            marketingSource: request.MarketingSource,
            marketingDetail: request.MarketingDetail,
            promoCode: request.PromoCode,
            offerType: request.OfferType);

        // ── No email / push here ──
        // The attendance is still RESERVED at this point — the customer
        // hasn't picked a payment method or paid. Sending a "Booking
        // Confirmed" email now would mislead customers who later abandon
        // checkout or whose Stripe payment fails.
        //
        // PaymentService is the single source of truth for the
        // RESERVED → BOOKED transition and owns BOTH the push fan-out
        // AND the confirmation email:
        //   • CreateIntentAsync   — zero-amount flows (PACKAGE_CREDIT,
        //                           PAY_AT_STUDIO) confirm immediately
        //   • MarkSucceededAsync  — Stripe success path

        return Ok(new
        {
            success = true,
            attendanceId = attendance.Id,
            bookingReference = attendance.BookingReference,
            className = session.ClassName,
            instructorName = session.InstructorName,
            startTime = session.StartTime,
            format = session.Format,
            quantity = attendance.Quantity,
            hasPackage = packageId != null,
            message = packageId != null
                ? "Your credit will be used when you check in at the studio."
                : "Please pay at the front desk upon arrival."
        });
    }
    catch (Exception ex)
    {
        return BadRequest(new { message = ex.Message });
    }
}

