function renderPackages() {
  const wrap = document.getElementById("packagesList");

  if (packages.length === 0) {
    document.getElementById("buyMoreBtn").style.display = "none";
    document.getElementById("tab-pkg-count").textContent = "";
    wrap.innerHTML = `
      <div class="sp-empty-state">
        <div class="sp-empty-state-icon">
          <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" style="width:32px;height:32px;">
            <rect x="3" y="3" width="18" height="18" rx="2"/><path d="M3 9h18M9 21V9"/>
          </svg>
        </div>
        <div class="sp-empty-state-title" data-i18n="packages.noPackage">${t("packages.noPackage")}</div>
        <div>${t("packages.noPackageDescription")}</div>
        <a href="/packages" class="sp-mypkg-empty-cta">${t("packages.browsePackages")}</a>
      </div>`;
    return;
  }

  // Sort: ACTIVE / LOW_BALANCE first, then newest activation
  const isActive = (s) => s === "ACTIVE" || s === "LOW_BALANCE";
  const sorted = [...packages].sort((a, b) => {
    if (isActive(a.status) && !isActive(b.status)) return -1;
    if (!isActive(a.status) && isActive(b.status)) return 1;
    return (new Date(b.activationDate || 0).getTime()) - (new Date(a.activationDate || 0).getTime());
  });

  // Apply format filter
  const filtered = activeFilter === "ALL"
    ? sorted
    : sorted.filter((p) => (p.format || "GROUP").toUpperCase() === activeFilter);

  // Update badge
  document.getElementById("tab-pkg-count").textContent = String(packages.length);

  if (filtered.length === 0) {
    wrap.innerHTML = `<div class="sp-filter-empty">No ${activeFilter.toLowerCase()} packages found.</div>`;

  wrap.innerHTML = usageBookings.map((b) => usageRow(b, pkgIdMap)).join("");
}

