let _packageProductsLoaded = false;

async function loadPackageProductsIfNeeded() {
  if (_packageProductsLoaded) return;
  const sel = document.getElementById('addPackageProduct');
  try {
    const r = await fetch(`${API}/api/product`, {
      headers: { Authorization: 'Bearer ' + token },
    });
    if (!r.ok) throw new Error('Failed to load packages');
    const products = await r.json();
    const packages = (products || []).filter(
      (p) => p.type === 'PACKAGE' && p.isActive !== false,
    );

    if (!packages.length) {
      sel.innerHTML = `<option value="">No active packages available</option>`;
    } else {
      sel.innerHTML =
        `<option value="">Select a package…</option>` +
        packages
          .map((p) => {
            const credits = p.credits > 0 ? p.credits : 1;
            const validity =
              p.validityDays > 0 ? `${p.validityDays}d validity` : 'no expiry';
            const fmt =
              p.formatRestriction && p.formatRestriction !== 'NONE'
                ? `${p.formatRestriction} · `
                : '';
            return `<option value="${p.id}">${p.name} — ${fmt}${credits} credits · ${validity}</option>`;
          })
          .join('');
    }
    _packageProductsLoaded = true;
  } catch (e) {
    sel.innerHTML = `<option value="">Failed to load packages</option>`;
  }
}

